 void SetupCaptureO(){world.NewGame(0);world.SimulationPaused=true;world.WalletFunds=100000;world.EnsureProbeCatalog();desktop.Clear();OpenExplorationF();explorationTabF=6;tabO=2;if(captureScene is "stage-o-wormholes" or "stage-o-residents" or "stage-o-fabricator"){var p=SourceCatalogO.Data.Systems.First(s=>s.Class==3&&s.EffectType>0);world.NewExploration43(p.Id);world.SimulationPaused=true;world.EnsureProbeCatalog();tabO=captureScene=="stage-o-wormholes"?0:captureScene=="stage-o-residents"?1:3;var e=world.Exploration.Encounters.First(e=>e.ProfileO?.Family==(tabO==3?"Fabricator":"Resident"));selectionO=e.Id;if(tabO==3){world.UtilitySites.First(s=>s.Id=="f:"+e.Id).Signal=100;world.EnterEncounterF("f:"+e.Id);}}}
 int checksUiO;
